-- Realistische Testdaten für 36 Monate (August 2023 bis Juli 2026)
-- ACHTUNG: Vorhandene Transaktionen, Themen und Tags werden ersetzt.
-- Der Kontostand wird in der Anwendung als Anfangsbestand + SUM(transaktionen.betrag) berechnet.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

DELETE FROM transaktionen_tags;
DELETE FROM transaktionen;
DELETE FROM tags;
DELETE FROM themen;
ALTER TABLE transaktionen AUTO_INCREMENT = 1;
ALTER TABLE tags AUTO_INCREMENT = 1;
ALTER TABLE themen AUTO_INCREMENT = 1;

UPDATE konten SET kontostand = 1000.00 WHERE id = 1;




-- Automatische Tag-Zuordnung anhand der Kategorien und Beschreibungen
SELECT t.id, tg.id FROM transaktionen t
JOIN themen th ON th.id = t.thema_id
JOIN tags tg ON tg.name = 'Fixkosten'
WHERE th.name IN ('Miete','Handy & Internet','Streaming','Auto-Leasing','Versicherungen','Strom & Energie','ÖPNV');

SELECT t.id, tg.id FROM transaktionen t JOIN tags tg ON tg.name = 'Monatlich'
WHERE t.beschreibung IN ('Monatsgehalt Arbeitgeber GmbH','Warmmiete Wohnung','Leasingrate Kompaktwagen','Internet und Mobilfunk','Disney+','Netflix Standard','Spotify','Kfz-Versicherung','Privathaftpflicht','Hausratversicherung','Stromabschlag','Deutschlandticket');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Vertrag'
WHERE th.name IN ('Miete','Handy & Internet','Streaming','Auto-Leasing','Versicherungen','Strom & Energie');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Versicherung'
WHERE th.name='Versicherungen';

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Mobilität'
WHERE th.name IN ('Auto-Leasing','Tanken','ÖPNV');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Unterhaltung'
WHERE th.name IN ('Streaming','Freizeit','Restaurant');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Haushalt'
WHERE th.name IN ('Miete','Lebensmittel','Haushaltswaren','Strom & Energie');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Gesundheit'
WHERE th.name IN ('Gesundheit','Kosmetik & Pflege');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Arbeit'
WHERE th.name IN ('Gehalt','Bonus');

SELECT t.id, tg.id FROM transaktionen t JOIN themen th ON th.id=t.thema_id JOIN tags tg ON tg.name='Alltag'
WHERE th.name IN ('Lebensmittel','Kosmetik & Pflege','Haushaltswaren','Kleidung','Restaurant');

SELECT t.id, tg.id FROM transaktionen t JOIN tags tg ON tg.name='Online'
WHERE t.beschreibung IN ('Disney+','Netflix Standard','Spotify','Internet und Mobilfunk');

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;

-- Kontrolle nach dem Import:
SELECT COUNT(*) AS anzahl_testbuchungen,
       SUM(CASE WHEN betrag > 0 THEN betrag ELSE 0 END) AS einnahmen,
       ABS(SUM(CASE WHEN betrag < 0 THEN betrag ELSE 0 END)) AS ausgaben,
       1000.00 + SUM(betrag) AS aktueller_kontostand
FROM transaktionen;
